import React from 'react';
import memelogo from '../assets/memecoin.png';

const NotFound = () => {
  return (
    <div className="min-h-screen bg-gradient-to-b from-[#0B041A] to-mystery-dark">
      <div className="container mx-auto px-4 py-16">
        <div className="flex flex-col lg:flex-row items-center justify-between gap-8">
          {/* Left side - Large logo */}
          <div className="lg:w-1/2">
            <img 
              src={memelogo} 
              alt="Memecoin Logo" 
              className="w-full max-w-[500px] mx-auto animate-float"
            />
          </div>
          
          {/* Right side - 404 message */}
          <div className="lg:w-1/2 text-center lg:text-left">
            <h1 className="font-heading text-8xl bg-gradient-to-r from-[#FF6B6B] via-[#FFE66D] to-[#4ECDC4] text-transparent bg-clip-text mb-6">
              404
            </h1>
            <h2 className="font-heading text-4xl text-white mb-4">
              MUCH EMPTY! VERY LOST! 🐕
            </h2>
            <p className="font-heading text-2xl text-gray-300 mb-8">
              WOW! Such wrong path! The memes you seek are not here, fren!
            </p>
            <a 
              href="/"
              className="font-heading px-8 py-3 rounded-full bg-mystery-accent text-white hover:opacity-90 transition-opacity inline-block"
            >
              Return to Meme Heaven
            </a>
          </div>
        </div>
      </div>
    </div>
  );
};

export default NotFound;
